from typing import List, Tuple, Dict, Any

def simulate_snake(
    board_size: Tuple[int, int],
    snake: List[Tuple[int, int]],
    food: List[Tuple[int, int]],
    moves: List[str]
) -> Tuple[List[Tuple[int, int]], bool, int]:
    width, height = board_size
    food_list = list(food)  # foodをmutableにする

    if not snake or len(snake) == 1 and snake[0] in food_list:
        return (snake.copy(), True, 0)

    alive = True
    head_x, head_y = snake[0][0], snake[0][1]

    def get_direction() -> Tuple[str, str]:
        if len(snake) > 1:
            hx, hy = snake[0][0], snake[0][1]
            px, py = snake[1][0], snake[1][1]
            if (hx, hy) != (px, py):
                dx = hx - px
                dy = hy - py
                if dx == 1:
                    return "RIGHT", True
                elif dx == -1:
                    return "LEFT", True
                elif dy == 1:
                    return "DOWN", True
                elif dy == -1:
                    return "UP", True
        return "", False

    def is_valid_head_pos(x, y) -> bool:
        if not (0 <= x < width and 0 <= y < height):
            return False
        for sx, sy in snake[1:]:
            if x == sx and y == sy:
                return False
        return True

    def apply_move(current_head_x, current_head_y, move_str) -> Tuple[int, int, bool]:
        if not move_str or move_str.lower() != move_str:
            move_str = "UP"
        dx = dy = 0
        if move_str == "RIGHT":
            dx = 1
        elif move_str == "LEFT":
            dx = -1
        elif move_str == "DOWN":
            dy = 1
        elif move_str == "UP":
            dy = -1
        next_x, next_y = current_head_x + dx, current_head_y + dy
        if not is_valid_head_pos(next_x, next_y):
            return current_head_x, current_head_y, False
        return next_x, next_y, True

    food_eaten = 0
    tail_staying = True
    new_head = snake[0][0], snake[0][1]

    for i, move in enumerate(moves):
        if not alive:
            break
        current_direction = get_direction()[0]
        new_head_x, new_head_y, valid = apply_move(new_head[0], new_head[1], move)
        if not valid:
            new_head_x, new_head_y = snake[0][0], snake[0][1]

        new_snake = [new_head] + list(snake)[:-1]
        tail_pos = snake[-1]
        if food_list and new_head == food_list[0]:
            food_eaten += 1
            food_list.pop(0)
            tail_staying = True
            food_count = len(food_list)
            if not food_count:
                food_list = []

        if tail_staying:
            new_snake.append(tail_pos)
            new_snake.remove(new_snake[-1])  # 尻尾を戻す
            del new_snake[-1]
        else:
            del new_snake[-1]

        snake = new_snake

    final_snake = snake if snake else [(0, 0)]
    return (final_snake, alive, food_eaten)
